cat > /workspace/src/commands.rs << 'EOFCMDS'
pub mod headers;
pub mod count;
pub mod select;
pub mod table;
pub mod search;
pub mod sort;
pub mod stats;
pub mod frequency;
pub mod slice;
pub mod flatten;
pub mod fmt;
pub mod cat;
pub mod index;
pub mod join;
pub mod split;
pub mod fixlengths;
pub mod sample;
pub mod reverse;
pub mod partition;
pub mod input;

use std::io::{self, BufRead, BufReader, Write};
use std::fs::File;
use csv::{Reader, ReaderBuilder, Writer, StringRecord};

pub fn get_delim(args: &[String]) -> u8 {
    for (i, arg) in args.iter().enumerate() {
        if (arg == "-d" || arg == "--delimiter") && i + 1 < args.len() {
            return args[i + 1].as_bytes()[0];
        }
    }
    b','
}

pub fn get_no_headers(args: &[String]) -> bool {
    args.iter().any(|a| a == "-n" || a == "--no-headers")
}

pub fn get_output_file(args: &[String]) -> Option<String> {
    for (i, arg) in args.iter().enumerate() {
        if (arg == "-o" || arg == "--output") && i + 1 < args.len() {
            return Some(args[i + 1].clone());
        }
    }
    None
}

pub fn get_input_file(args: &[String]) -> Option<String> {
    for arg in args.iter().rev() {
        if !arg.starts_with('-') && arg != "rows" && arg != "columns" {
            return Some(arg.clone());
        }
    }
    None
}

pub fn get_reader(input: Option<String>, delim: u8) -> csv::Result<Reader<Box<dyn io::Read>>> {
    let reader: Box<dyn io::Read> = match input {
        Some(path) => Box::new(File::open(&path)?),
        None => Box::new(io::stdin()),
    };

    let mut builder = ReaderBuilder::new();
    builder.delimiter(delim);
    Ok(builder.from_reader(reader))
}

pub fn get_writer(output: Option<String>, delim: u8) -> csv::Result<Writer<Box<dyn io::Write>>> {
    let writer: Box<dyn io::Write> = match output {
        Some(path) => Box::new(File::create(&path)?),
        None => Box::new(io::stdout()),
    };

    let mut wtr = Writer::new(writer);
    wtr.delimiter(delim);
    Ok(wtr)
}

pub fn read_all_records(input: Option<String>, delim: u8, has_headers: bool) -> csv::Result<(Option<StringRecord>, Vec<StringRecord>)> {
    let mut reader = get_reader(input, delim)?;
    let headers = if has_headers {
        Some(reader.headers()?.clone())
    } else {
        None
    };

    let mut records = Vec::new();
    for result in reader.records() {
        records.push(result?);
    }

    Ok((headers, records))
}
