use csv::{Reader, ReaderBuilder};
use std::io;
use std::fs::File;

pub fn run(args: &[String]) {
    if args.is_empty() || args[0] == "--help" || args[0] == "-h" {
        print_help();
        return;
    }

    let mut just_names = false;
    let mut intersect = false;
    let mut delimiter = b',';
    let mut files = Vec::new();

    let mut i = 0;
    while i < args.len() {
        match args[i].as_str() {
            "-j" | "--just-names" => just_names = true,
            "--intersect" => intersect = true,
            "-d" | "--delimiter" => {
                i += 1;
                if i < args.len() {
                    delimiter = args[i].as_bytes()[0];
                }
            }
            "-h" | "--help" => {
                print_help();
                return;
            }
            arg if !arg.starts_with('-') => files.push(arg.to_string()),
            _ => {}
        }
        i += 1;
    }

    if files.is_empty() {
        files.push("-".to_string());
    }

    if files.len() > 1 {
        just_names = true;
    }

    if intersect {
        print_intersect(&files, delimiter);
    } else {
        for (idx, file) in files.iter().enumerate() {
            if idx > 0 {
                println!();
            }
            print_headers(&file, delimiter, just_names);
        }
    }
}

fn print_headers(file: &str, delimiter: u8, just_names: bool) {
    let reader: Box<dyn io::Read> = if file == "-" {
        Box::new(io::stdin())
    } else {
        match File::open(file) {
            Ok(f) => Box::new(f),
            Err(e) => {
                eprintln!("Error opening file: {}", e);
                return;
            }
        }
    };

    let mut builder = ReaderBuilder::new();
    builder.delimiter(delimiter);
    let reader = match builder.from_reader(reader).headers() {
        Ok(h) => h.clone(),
        Err(e) => {
            eprintln!("Error reading headers: {}", e);
            return;
        }
    };

    for (i, header) in reader.iter().enumerate() {
        if just_names {
            println!("{}", header);
        } else {
            println!("{}\t{}", i + 1, header);
        }
    }
}

fn print_intersect(files: &[String], delimiter: u8) {
    let mut headers_list = Vec::new();

    for file in files {
        let reader: Box<dyn io::Read> = if file == "-" {
            Box::new(io::stdin())
        } else {
            match File::open(file) {
                Ok(f) => Box::new(f),
                Err(e) => {
                    eprintln!("Error opening file: {}", e);
                    return;
                }
            }
        };

        let mut builder = ReaderBuilder::new();
        builder.delimiter(delimiter);
        let reader = match builder.from_reader(reader).headers() {
            Ok(h) => h.clone(),
            Err(e) => {
                eprintln!("Error reading headers: {}", e);
                return;
            }
        };

        headers_list.push(reader.iter().map(|s| s.to_string()).collect::<Vec<_>>());
    }

    if headers_list.is_empty() {
        return;
    }

    // Find intersection
    let mut result = headers_list[0].clone();
    for other in headers_list.iter().skip(1) {
        result.retain(|h| other.contains(h));
    }

    for header in result {
        println!("{}", header);
    }
}

fn print_help() {
    println!("Prints the fields of the first row in the CSV data.");
    println!();
    println!("These names can be used in commands like 'select' to refer to columns in the");
    println!("CSV data.");
    println!();
    println!("Note that multiple CSV files may be given to this command. This is useful with");
    println!("the --intersect flag.");
    println!();
    println!("Usage:");
    println!("    xsv headers [options] [<input>...]");
    println!();
    println!("headers options:");
    println!("    -j, --just-names       Only show the header names (hide column index).");
    println!("                           This is automatically enabled if more than one");
    println!("                           input is given.");
    println!("    --intersect            Shows the intersection of all headers in all of");
    println!("                           the inputs given.");
    println!();
    println!("Common options:");
    println!("    -h, --help             Display this message");
    println!("    -d, --delimiter <arg>  The field delimiter for reading CSV data.");
    println!("                           Must be a single character. (default: ,)");
}
