use std::io::{self, Read, BufRead, BufReader};
use std::fs::File;

#[derive(Clone, Debug)]
pub struct Record(pub Vec<String>);

impl Record {
    pub fn len(&self) -> usize {
        self.0.len()
    }

    pub fn is_empty(&self) -> bool {
        self.0.is_empty()
    }

    pub fn get(&self, idx: usize) -> Option<&str> {
        self.0.get(idx).map(|s| s.as_str())
    }

    pub fn iter(&self) -> impl Iterator<Item = &str> {
        self.0.iter().map(|s| s.as_str())
    }
}

pub struct CsvReader {
    reader: BufReader<Box<dyn Read>>,
    delimiter: u8,
    has_headers: bool,
    headers: Option<Record>,
}

impl CsvReader {
    pub fn new(input: Option<String>, delimiter: u8, has_headers: bool) -> io::Result<Self> {
        let reader: Box<dyn Read> = match input {
            Some(path) => Box::new(File::open(&path)?),
            None => Box::new(io::stdin()),
        };

        let buf_reader = BufReader::new(reader);
        let mut csv = CsvReader {
            reader: buf_reader,
            delimiter,
            has_headers,
            headers: None,
        };

        if has_headers {
            let mut line = String::new();
            csv.reader.read_line(&mut line)?;
            csv.headers = Some(parse_csv_line(&line, delimiter));
        }

        Ok(csv)
    }

    pub fn headers(&self) -> Option<&Record> {
        self.headers.as_ref()
    }

    pub fn records(&mut self) -> impl Iterator<Item = io::Result<Record>> + '_ {
        std::iter::from_fn(move || {
            let mut line = String::new();
            match self.reader.read_line(&mut line) {
                Ok(0) => None,
                Ok(_) => {
                    if line.ends_with('\n') {
                        line.pop();
                        if line.ends_with('\r') {
                            line.pop();
                        }
                    }
                    Some(Ok(parse_csv_line(&line, self.delimiter)))
                }
                Err(e) => Some(Err(e)),
            }
        })
    }
}

pub fn parse_csv_line(line: &str, delimiter: u8) -> Record {
    let delimiter_char = delimiter as char;
    let mut fields = Vec::new();
    let mut current = String::new();
    let mut in_quotes = false;
    let mut chars = line.chars().peekable();

    while let Some(ch) = chars.next() {
        if ch == '"' {
            if in_quotes {
                // Check for escaped quote
                if chars.peek() == Some(&'"') {
                    chars.next();
                    current.push('"');
                } else {
                    in_quotes = false;
                }
            } else {
                in_quotes = true;
            }
        } else if ch == delimiter_char && !in_quotes {
            fields.push(current.clone());
            current.clear();
        } else {
            current.push(ch);
        }
    }

    fields.push(current);
    Record(fields)
}

pub fn write_csv_line(fields: &[&str], delimiter: u8, output: &mut dyn std::io::Write) -> io::Result<()> {
    let delimiter_char = delimiter as char;
    for (i, field) in fields.iter().enumerate() {
        if i > 0 {
            write!(output, "{}", delimiter_char)?;
        }

        // Check if field needs quoting
        if field.contains('"') || field.contains(delimiter_char) || field.contains('\n') || field.contains('\r') {
            write!(output, "\"")?;
            for ch in field.chars() {
                if ch == '"' {
                    write!(output, "\"\"")?;
                } else {
                    write!(output, "{}", ch)?;
                }
            }
            write!(output, "\"")?;
        } else {
            write!(output, "{}", field)?;
        }
    }
    writeln!(output)?;
    Ok(())
}

pub fn get_delim(args: &[String]) -> u8 {
    for (i, arg) in args.iter().enumerate() {
        if (arg == "-d" || arg == "--delimiter") && i + 1 < args.len() {
            return args[i + 1].as_bytes()[0];
        }
    }
    b','
}

pub fn get_no_headers(args: &[String]) -> bool {
    args.iter().any(|a| a == "-n" || a == "--no-headers")
}

pub fn get_output_file(args: &[String]) -> Option<String> {
    for (i, arg) in args.iter().enumerate() {
        if (arg == "-o" || arg == "--output") && i + 1 < args.len() {
            return Some(args[i + 1].clone());
        }
    }
    None
}

pub fn get_input_file(args: &[String]) -> Option<String> {
    for arg in args.iter().rev() {
        if !arg.starts_with('-') && arg != "rows" && arg != "columns" {
            return Some(arg.clone());
        }
    }
    None
}

pub fn read_all_records(input: Option<String>, delim: u8, has_headers: bool) -> io::Result<(Option<Record>, Vec<Record>)> {
    let mut reader = CsvReader::new(input, delim, has_headers)?;
    let headers = reader.headers().cloned();

    let mut records = Vec::new();
    for result in reader.records() {
        records.push(result?);
    }

    Ok((headers, records))
}
