use crate::csv_util::{CsvReader, get_delim, get_input_file};
use std::io;

pub fn run(args: &[String]) {
    if args.iter().any(|a| a == "--help" || a == "-h") {
        print_help();
        return;
    }

    let delimiter = get_delim(args);
    let input = get_input_file(args);

    let mut width = 2;
    let mut pad = 2;
    let mut condense = None;

    for (i, arg) in args.iter().enumerate() {
        match arg.as_str() {
            "-w" | "--width" => {
                if i + 1 < args.len() {
                    width = args[i + 1].parse().unwrap_or(2);
                }
            }
            "-p" | "--pad" => {
                if i + 1 < args.len() {
                    pad = args[i + 1].parse().unwrap_or(2);
                }
            }
            "-c" | "--condense" => {
                if i + 1 < args.len() {
                    condense = args[i + 1].parse().ok();
                }
            }
            _ => {}
        }
    }

    match CsvReader::new(input, delimiter, true) {
        Ok(mut reader) => {
            let mut all_records = Vec::new();

            if let Some(headers) = reader.headers() {
                all_records.push(headers.0.clone());
            }

            for result in reader.records() {
                if let Ok(record) = result {
                    all_records.push(record.0);
                }
            }

            if all_records.is_empty() {
                return;
            }

            let num_cols = all_records[0].len();
            let mut col_widths = vec![width; num_cols];

            for row in &all_records {
                for (i, cell) in row.iter().enumerate() {
                    let len = if let Some(c) = condense {
                        cell.chars().take(c).count()
                    } else {
                        cell.chars().count()
                    };
                    col_widths[i] = col_widths[i].max(len);
                }
            }

            for row in &all_records {
                for (i, cell) in row.iter().enumerate() {
                    let display = if let Some(c) = condense {
                        let truncated: String = cell.chars().take(c).collect();
                        if cell.chars().count() > c {
                            truncated + "..."
                        } else {
                            truncated
                        }
                    } else {
                        cell.clone()
                    };

                    if i > 0 {
                        print!("{}", " ".repeat(pad));
                    }
                    print!("{:<width$}", display, width = col_widths[i]);
                }
                println!();
            }
        }
        Err(e) => {
            eprintln!("Error: {}", e);
            std::process::exit(1);
        }
    }
}

fn print_help() {
    println!("Outputs CSV data as a table with columns in alignment.");
}
