use crate::csv_util::{CsvReader, get_delim, get_no_headers, get_output_file, get_input_file};
use std::io::{self, Write, BufWriter};
use std::fs::File;

pub fn run(args: &[String]) {
    if args.iter().any(|a| a == "--help" || a == "-h") {
        print_help();
        return;
    }

    let delimiter = get_delim(args);
    let has_headers = !get_no_headers(args);
    let output = get_output_file(args);

    let mut regex_pattern = String::new();
    let mut input_file = None;
    let mut ignore_case = false;
    let mut invert = false;
    let mut select_cols = None;

    let mut i = 0;
    while i < args.len() {
        match args[i].as_str() {
            "-i" | "--ignore-case" => ignore_case = true,
            "-v" | "--invert-match" => invert = true,
            "-s" | "--select" => {
                i += 1;
                if i < args.len() {
                    select_cols = Some(args[i].clone());
                }
            }
            "-d" | "--delimiter" => {
                i += 1;
            }
            "-o" | "--output" => {
                i += 1;
            }
            "-n" | "--no-headers" => {}
            arg if regex_pattern.is_empty() && !arg.starts_with('-') => {
                regex_pattern = arg.to_string();
            }
            arg if !arg.starts_with('-') => {
                input_file = Some(arg.to_string());
            }
            _ => {}
        }
        i += 1;
    }

    if regex_pattern.is_empty() {
        eprintln!("Error: regex required");
        std::process::exit(1);
    }

    let pattern = if ignore_case {
        format!("(?i){}", regex_pattern)
    } else {
        regex_pattern
    };

    match CsvReader::new(input_file, delimiter, has_headers) {
        Ok(mut reader) => {
            let writer_box: Box<dyn Write> = match output {
                Some(path) => Box::new(BufWriter::new(File::create(&path).unwrap())),
                None => Box::new(BufWriter::new(io::stdout())),
            };
            let mut writer = writer_box;

            if let Some(headers) = reader.headers() {
                let _ = writeln!(writer, "{}", headers.0.join(&(delimiter as char).to_string()));
            }

            for result in reader.records() {
                if let Ok(record) = result {
                    let matches = simple_regex_match(&pattern, &record.0);
                    if matches != invert {
                        let _ = writeln!(writer, "{}", record.0.join(&(delimiter as char).to_string()));
                    }
                }
            }
        }
        Err(e) => {
            eprintln!("Error: {}", e);
            std::process::exit(1);
        }
    }
}

fn simple_regex_match(pattern: &str, fields: &[String]) -> bool {
    for field in fields {
        if simple_match(pattern, field) {
            return true;
        }
    }
    false
}

fn simple_match(pattern: &str, text: &str) -> bool {
    if pattern.starts_with("(?i)") {
        let p = &pattern[4..];
        text.to_lowercase().contains(&p.to_lowercase())
    } else {
        text.contains(pattern)
    }
}

fn print_help() {
    println!("Filters CSV data by whether the given regex matches a row.");
}
