use crate::csv_util::{CsvReader, get_delim, get_no_headers, get_output_file, get_input_file};
use std::io::{self, Write, BufWriter};
use std::fs::File;

pub fn run(args: &[String]) {
    let delimiter = get_delim(args);
    let has_headers = !get_no_headers(args);
    let output = get_output_file(args);
    let input = get_input_file(args);

    let mut start = 0;
    let mut end = None;
    let mut len = None;
    let mut index = None;

    let mut i = 0;
    while i < args.len() {
        match args[i].as_str() {
            "-s" | "--start" => {
                i += 1;
                if i < args.len() {
                    start = args[i].parse().unwrap_or(0);
                }
            }
            "-e" | "--end" => {
                i += 1;
                if i < args.len() {
                    end = args[i].parse().ok();
                }
            }
            "-l" | "--len" => {
                i += 1;
                if i < args.len() {
                    len = args[i].parse().ok();
                }
            }
            "-i" | "--index" => {
                i += 1;
                if i < args.len() {
                    index = args[i].parse().ok();
                }
            }
            _ => {}
        }
        i += 1;
    }

    if let Some(idx) = index {
        start = idx;
        len = Some(1);
    }

    let actual_end = if let Some(l) = len {
        Some(start + l)
    } else {
        end
    };

    match CsvReader::new(input, delimiter, has_headers) {
        Ok(mut reader) => {
            let headers = reader.headers().cloned();
            let writer_box: Box<dyn Write> = match output {
                Some(path) => Box::new(BufWriter::new(File::create(&path).unwrap())),
                None => Box::new(BufWriter::new(io::stdout())),
            };
            let mut writer = writer_box;

            if let Some(h) = headers {
                let _ = writeln!(writer, "{}", h.0.join(&(delimiter as char).to_string()));
            }

            let mut record_idx = 0;
            for result in reader.records() {
                if let Ok(record) = result {
                    if record_idx >= start && actual_end.map(|e| record_idx < e).unwrap_or(true) {
                        let _ = writeln!(writer, "{}", record.0.join(&(delimiter as char).to_string()));
                    }
                    record_idx += 1;
                }
            }
        }
        Err(e) => {
            eprintln!("Error: {}", e);
            std::process::exit(1);
        }
    }
}
