use crate::csv_util::{CsvReader, get_delim, get_no_headers, get_input_file};
use std::collections::HashMap;

pub fn run(args: &[String]) {
    let delimiter = get_delim(args);
    let has_headers = !get_no_headers(args);
    let input = get_input_file(args);

    match CsvReader::new(input, delimiter, has_headers) {
        Ok(mut reader) => {
            let headers = reader.headers().cloned();
            let mut records = Vec::new();

            for result in reader.records() {
                if let Ok(record) = result {
                    records.push(record);
                }
            }

            if records.is_empty() {
                return;
            }

            let num_cols = records[0].len();
            println!("field,type,sum,min,max,min_length,max_length,mean,stddev");

            for col in 0..num_cols {
                let name = headers.as_ref().and_then(|h| h.0.get(col)).map(|s| s.as_str()).unwrap_or(&col.to_string());
                let mut values = Vec::new();
                let mut nums = Vec::new();

                for record in &records {
                    if let Some(v) = record.0.get(col) {
                        values.push(v.clone());
                        if let Ok(n) = v.parse::<f64>() {
                            nums.push(n);
                        }
                    }
                }

                let is_numeric = !nums.is_empty() && nums.len() == values.len();
                let typ = if is_numeric { "Integer" } else { "Unicode" };

                let sum = if is_numeric { nums.iter().sum::<f64>() } else { 0.0 };
                let min = if is_numeric { nums.iter().cloned().fold(f64::INFINITY, f64::min) } else { 0.0 };
                let max = if is_numeric { nums.iter().cloned().fold(f64::NEG_INFINITY, f64::max) } else { 0.0 };

                let mut lengths: Vec<usize> = values.iter().map(|v| v.chars().count()).collect();
                lengths.sort();
                let min_len = lengths.first().copied().unwrap_or(0);
                let max_len = lengths.last().copied().unwrap_or(0);

                let mean = if is_numeric && !nums.is_empty() {
                    nums.iter().sum::<f64>() / nums.len() as f64
                } else {
                    0.0
                };

                let variance = if is_numeric && !nums.is_empty() {
                    nums.iter().map(|n| (n - mean).powi(2)).sum::<f64>() / nums.len() as f64
                } else {
                    0.0
                };
                let stddev = variance.sqrt();

                let sum_str = if is_numeric && sum != 0.0 { sum.to_string() } else { "".to_string() };
                let min_str = if is_numeric { min.to_string() } else { values.iter().min().cloned().unwrap_or_default() };
                let max_str = if is_numeric { max.to_string() } else { values.iter().max().cloned().unwrap_or_default() };

                println!("{},{},{},{},{},{},{},{},{}", 
                    name, typ, sum_str, min_str, max_str, min_len, max_len,
                    if is_numeric { mean.to_string() } else { "".to_string() },
                    if is_numeric { stddev.to_string() } else { "".to_string() }
                );
            }
        }
        Err(e) => {
            eprintln!("Error: {}", e);
            std::process::exit(1);
        }
    }
}
