use crate::csv_util::{CsvReader, get_delim, get_no_headers, get_output_file, get_input_file};
use std::io::{self, Write, BufWriter};
use std::fs::File;

pub fn run(args: &[String]) {
    let delimiter = get_delim(args);
    let out_delimiter = get_out_delim(args).unwrap_or(delimiter);
    let has_headers = !get_no_headers(args);
    let output = get_output_file(args);
    let input = get_input_file(args);

    match CsvReader::new(input, delimiter, has_headers) {
        Ok(mut reader) => {
            let headers = reader.headers().cloned();
            let writer_box: Box<dyn Write> = match output {
                Some(path) => Box::new(BufWriter::new(File::create(&path).unwrap())),
                None => Box::new(BufWriter::new(io::stdout())),
            };
            let mut writer = writer_box;

            if let Some(h) = headers {
                let _ = writeln!(writer, "{}", h.0.join(&(out_delimiter as char).to_string()));
            }

            for result in reader.records() {
                if let Ok(record) = result {
                    let _ = writeln!(writer, "{}", record.0.join(&(out_delimiter as char).to_string()));
                }
            }
        }
        Err(e) => {
            eprintln!("Error: {}", e);
            std::process::exit(1);
        }
    }
}

fn get_out_delim(args: &[String]) -> Option<u8> {
    for (i, arg) in args.iter().enumerate() {
        if (arg == "-t" || arg == "--out-delimiter") && i + 1 < args.len() {
            return Some(args[i + 1].as_bytes()[0]);
        }
    }
    None
}
