use crate::csv_util::{CsvReader, get_delim, get_no_headers, get_output_file};
use std::io::{self, Write, BufWriter};
use std::fs::File;

pub fn run(args: &[String]) {
    let delimiter = get_delim(args);
    let has_headers = !get_no_headers(args);
    let output = get_output_file(args);

    let mut mode = "rows";
    let mut files = Vec::new();
    let mut pad = false;

    for (i, arg) in args.iter().enumerate() {
        match arg.as_str() {
            "rows" | "columns" => mode = arg,
            "-p" | "--pad" => pad = true,
            _ if !arg.starts_with('-') && (i == 0 || !args[i - 1].starts_with('-')) => {
                if arg != "rows" && arg != "columns" {
                    files.push(arg.clone());
                }
            }
            _ => {}
        }
    }

    if files.is_empty() {
        eprintln!("Error: at least one input file required");
        std::process::exit(1);
    }

    let writer_box: Box<dyn Write> = match output {
        Some(path) => Box::new(BufWriter::new(File::create(&path).unwrap())),
        None => Box::new(BufWriter::new(io::stdout())),
    };
    let mut writer = writer_box;

    if mode == "rows" {
        let mut first = true;
        for file in &files {
            if let Ok(mut reader) = CsvReader::new(Some(file.clone()), delimiter, has_headers) {
                if first {
                    if let Some(h) = reader.headers() {
                        let _ = writeln!(writer, "{}", h.0.join(&(delimiter as char).to_string()));
                    }
                    first = false;
                }
                for result in reader.records() {
                    if let Ok(record) = result {
                        let _ = writeln!(writer, "{}", record.0.join(&(delimiter as char).to_string()));
                    }
                }
            }
        }
    } else {
        let mut all_records = Vec::new();
        for file in &files {
            if let Ok(mut reader) = CsvReader::new(Some(file.clone()), delimiter, true) {
                for result in reader.records() {
                    if let Ok(record) = result {
                        all_records.push(record);
                    }
                }
            }
        }

        if !all_records.is_empty() {
            let max_cols = all_records.iter().map(|r| r.0.len()).max().unwrap_or(0);
            for i in 0..max_cols {
                let row: Vec<String> = all_records.iter().map(|r| r.0.get(i).cloned().unwrap_or_default()).collect();
                let _ = writeln!(writer, "{}", row.join(&(delimiter as char).to_string()));
            }
        }
    }
}
