use crate::csv_util::{CsvReader, get_delim, get_no_headers, get_input_file};
use std::collections::HashMap;

pub fn run(args: &[String]) {
    let delimiter = get_delim(args);
    let has_headers = !get_no_headers(args);
    let input = get_input_file(args);

    let mut limit = 10;
    let mut asc = false;

    for (i, arg) in args.iter().enumerate() {
        match arg.as_str() {
            "-l" | "--limit" => {
                if i + 1 < args.len() {
                    limit = args[i + 1].parse().unwrap_or(10);
                }
            }
            "-a" | "--asc" => asc = true,
            _ => {}
        }
    }

    match CsvReader::new(input, delimiter, has_headers) {
        Ok(mut reader) => {
            let headers = reader.headers().cloned();
            let mut freq_tables = Vec::new();
            let num_cols = if let Some(ref h) = headers { h.len() } else { 0 };

            for _ in 0..num_cols {
                freq_tables.push(HashMap::new());
            }

            for result in reader.records() {
                if let Ok(record) = result {
                    for (i, value) in record.0.iter().enumerate() {
                        if i < freq_tables.len() {
                            *freq_tables[i].entry(value.clone()).or_insert(0) += 1;
                        }
                    }
                }
