use crate::csv_util::{CsvReader, Record, get_delim, get_no_headers, get_output_file};
use std::io::{self, Write, BufWriter};
use std::fs::File;

pub fn run(args: &[String]) {
    if args.is_empty() || args.iter().any(|a| a == "--help" || a == "-h") {
        print_help();
        return;
    }

    let delimiter = get_delim(args);
    let has_headers = !get_no_headers(args);
    let output = get_output_file(args);

    let mut selection = String::new();
    let mut input_file = None;
    let mut found_selection = false;

    for (i, arg) in args.iter().enumerate() {
        match arg.as_str() {
            "--" => {
                if i + 1 < args.len() && !found_selection {
                    selection = args[i + 1].clone();
                    found_selection = true;
                    if i + 2 < args.len() {
                        input_file = Some(args[i + 2].clone());
                    }
                }
                break;
            }
            "-d" | "--delimiter" | "-o" | "--output" | "-n" | "--no-headers" => {}
            arg if arg.starts_with('-') => {}
            _ => {
                if !found_selection && selection.is_empty() {
                    selection = arg.clone();
                    found_selection = true;
                } else if found_selection && input_file.is_none() {
                    input_file = Some(arg.clone());
                }
            }
        }
    }

    if selection.is_empty() {
        eprintln!("Error: selection required");
        std::process::exit(1);
    }

    match CsvReader::new(input_file, delimiter, has_headers) {
        Ok(mut reader) => {
            let writer_box: Box<dyn Write> = match output {
                Some(path) => Box::new(BufWriter::new(File::create(&path).unwrap())),
                None => Box::new(BufWriter::new(io::stdout())),
            };
            let mut writer = writer_box;

            let headers = reader.headers().cloned();
            let indices = parse_selection(&selection, headers.as_ref());

            if let Some(h) = headers {
                let selected_headers: Vec<String> = indices.iter()
                    .filter_map(|&i| h.0.get(i).cloned())
                    .collect();
                let _ = writeln!(writer, "{}", selected_headers.join(&(delimiter as char).to_string()));
            }

            for result in reader.records() {
                if let Ok(record) = result {
                    let selected: Vec<String> = indices.iter()
                        .filter_map(|&i| record.0.get(i).cloned())
                        .collect();
                    let _ = writeln!(writer, "{}", selected.join(&(delimiter as char).to_string()));
                }
            }
        }
        Err(e) => {
            eprintln!("Error: {}", e);
            std::process::exit(1);
        }
    }
}

fn parse_selection(selection: &str, headers: Option<&Record>) -> Vec<usize> {
    let mut indices = Vec::new();

    for part in selection.split(',') {
        let part = part.trim();

        if part.contains('-') {
            let parts: Vec<&str> = part.splitn(2, '-').collect();
            let start_str = parts[0];
            let end_str = if parts.len() > 1 { parts[1] } else { "" };

            let start = if start_str.is_empty() {
                0
            } else if let Ok(n) = start_str.parse::<usize>() {
                n.saturating_sub(1)
            } else {
                find_header_index(start_str, headers).unwrap_or(0)
            };

            let end = if end_str.is_empty() {
                if let Some(h) = headers {
                    h.len().saturating_sub(1)
                } else {
                    usize::MAX
                }
            } else if let Ok(n) = end_str.parse::<usize>() {
                n.saturating_sub(1)
            } else {
                find_header_index(end_str, headers).unwrap_or(usize::MAX)
            };

            for i in start..=end.min(1000) {
                indices.push(i);
            }
        } else if let Ok(n) = part.parse::<usize>() {
            indices.push(n.saturating_sub(1));
        } else {
            if let Some(idx) = find_header_index(part, headers) {
                indices.push(idx);
            }
        }
    }

    indices
}

fn find_header_index(name: &str, headers: Option<&Record>) -> Option<usize> {
    headers?.0.iter().position(|h| h == name)
}

fn print_help() {
    println!("Select columns from CSV data efficiently.");
    println!();
    println!("Usage:");
    println!("    xsv select [options] [--] <selection> [<input>]");
    println!();
    println!("Common options:");
    println!("    -h, --help             Display this message");
    println!("    -o, --output <file>    Write output to <file> instead of stdout.");
    println!("    -n, --no-headers       When set, the first row will not be interpreted");
    println!("                           as headers.");
    println!("    -d, --delimiter <arg>  The field delimiter for reading CSV data.");
}
