use std::io::{self, Write, BufWriter};
use std::fs::File;

pub fn run(args: &[String]) {
    let delimiter = get_delim(args);
    let has_headers = !get_no_headers(args);
    let output = get_output_file(args);

    let mut sample_size = 10;
    let mut seed = 42u64;
    let mut input_file = None;

    let mut i = 0;
    while i < args.len() {
        match args[i].as_str() {
            "--seed" => {
                i += 1;
                if i < args.len() {
                    seed = args[i].parse().unwrap_or(42);
                }
            }
            arg if arg.parse::<usize>().is_ok() && sample_size == 10 => {
                sample_size = arg.parse().unwrap();
            }
            arg if !arg.starts_with('-') && input_file.is_none() && arg.parse::<usize>().is_err() => {
                input_file = Some(arg.to_string());
            }
            _ => {}
        }
        i += 1;
    }

    match CsvReader::new(input_file, delimiter, has_headers) {
        Ok(mut reader) => {
            let headers = reader.headers().cloned();
            let mut records = Vec::new();

            for result in reader.records() {
                if let Ok(record) = result {
                    records.push(record);
                }
            }

            let mut rng = seed;
            let mut sampled = Vec::new();

            for record in &records {
                rng = rng.wrapping_mul(1103515245).wrapping_add(12345);
                if (rng % records.len() as u64) < sample_size as u64 {
                    sampled.push(record.clone());
                }
            }

            // Ensure we have exactly sample_size items
            if sampled.len() > sample_size {
                sampled.truncate(sample_size);
            }

            let writer_box: Box<dyn Write> = match output {
                Some(path) => Box::new(BufWriter::new(File::create(&path).unwrap())),
                None => Box::new(BufWriter::new(io::stdout())),
            };
            let mut writer = writer_box;

            if let Some(h) = headers {
                let _ = writeln!(writer, "{}", h.0.join(&(delimiter as char).to_string()));
            }

            for record in sampled {
                let _ = writeln!(writer, "{}", record.0.join(&(delimiter as char).to_string()));
            }
        }
        Err(e) => {
            eprintln!("Error: {}", e);
            std::process::exit(1);
        }
    }
}
