use crate::csv_util::{CsvReader, get_delim, get_no_headers, get_input_file};
use std::io::{Write, BufWriter};
use std::fs::{File, create_dir_all};

pub fn run(args: &[String]) {
    let delimiter = get_delim(args);
    let has_headers = !get_no_headers(args);
    let input = get_input_file(args);

    let mut size = 500;
    let mut outdir = String::new();

    for (i, arg) in args.iter().enumerate() {
        match arg.as_str() {
            "-s" | "--size" => {
                if i + 1 < args.len() {
                    size = args[i + 1].parse().unwrap_or(500);
                }
            }
            arg if !arg.starts_with('-') && outdir.is_empty() && arg != "rows" && arg != "columns" => {
                outdir = arg.to_string();
            }
            _ => {}
        }
    }

    if outdir.is_empty() {
        eprintln!("Error: output directory required");
        std::process::exit(1);
    }

    let _ = create_dir_all(&outdir);

    match CsvReader::new(input, delimiter, has_headers) {
        Ok(mut reader) => {
            let headers = reader.headers().cloned();
            let mut chunk_num = 0;
            let mut record_count = 0;
            let mut current_file: Option<(BufWriter<File>, String)> = None;

            for result in reader.records() {
                if let Ok(record) = result {
                    if record_count % size == 0 {
                        if let Some((mut f, _)) = current_file.take() {
                            let _ = f.flush();
                        }
                        let filename = format!("{}/{}.csv", outdir, chunk_num * size);
                        let file = File::create(&filename).unwrap();
                        let mut writer = BufWriter::new(file);

                        if let Some(ref h) = headers {
                            let _ = writeln!(writer, "{}", h.0.join(&(delimiter as char).to_string()));
                        }
                        current_file = Some((writer, filename));
                    }

                    if let Some((ref mut writer, _)) = current_file {
                        let _ = writeln!(writer, "{}", record.0.join(&(delimiter as char).to_string()));
                    }

                    record_count += 1;
                    if record_count % size == 0 {
                        chunk_num += 1;
                    }
                }
            }
        }
        Err(e) => {
            eprintln!("Error: {}", e);
            std::process::exit(1);
        }
    }
}
EOF

