use crate::csv_util::{CsvReader, Record, get_delim, get_no_headers, get_output_file, get_input_file};
use std::io::{self, Write, BufWriter};
use std::fs::File;

pub fn run(args: &[String]) {
    if args.iter().any(|a| a == "--help" || a == "-h") {
        print_help();
        return;
    }

    let delimiter = get_delim(args);
    let has_headers = !get_no_headers(args);
    let output = get_output_file(args);

    let mut numeric = false;
    let mut reverse = false;
    let mut select_col = None;

    let mut i = 0;
    while i < args.len() {
        match args[i].as_str() {
            "-N" | "--numeric" => numeric = true,
            "-R" | "--reverse" => reverse = true,
            "-s" | "--select" => {
                i += 1;
                if i < args.len() {
                    select_col = Some(args[i].clone());
                }
            }
            _ => {}
        }
        i += 1;
    }

    let input = get_input_file(args);

    match CsvReader::new(input, delimiter, has_headers) {
        Ok(mut reader) => {
            let headers = reader.headers().cloned();
            let mut records = Vec::new();

            for result in reader.records() {
                if let Ok(record) = result {
                    records.push(record);
                }
            }

            let sort_col_idx = if let Some(col_name) = select_col {
                if let Some(ref h) = headers {
                    h.0.iter().position(|h| h == &col_name).unwrap_or(0)
                } else {
                    col_name.parse::<usize>().unwrap_or(0).saturating_sub(1)
                }
            } else {
                0
            };

            records.sort_by(|a, b| {
                let a_val = a.0.get(sort_col_idx).map(|s| s.as_str()).unwrap_or("");
                let b_val = b.0.get(sort_col_idx).map(|s| s.as_str()).unwrap_or("");

                let cmp = if numeric {
                    let av = a_val.parse::<f64>().unwrap_or(f64::NEG_INFINITY);
                    let bv = b_val.parse::<f64>().unwrap_or(f64::NEG_INFINITY);
                    av.partial_cmp(&bv).unwrap_or(std::cmp::Ordering::Equal)
                } else {
                    a_val.cmp(b_val)
                };

                if reverse {
                    cmp.reverse()
                } else {
                    cmp
                }
            });

            let writer_box: Box<dyn Write> = match output {
                Some(path) => Box::new(BufWriter::new(File::create(&path).unwrap())),
                None => Box::new(BufWriter::new(io::stdout())),
            };
            let mut writer = writer_box;

            if let Some(h) = headers {
                let _ = writeln!(writer, "{}", h.0.join(&(delimiter as char).to_string()));
            }

            for record in records {
                let _ = writeln!(writer, "{}", record.0.join(&(delimiter as char).to_string()));
            }
        }
        Err(e) => {
            eprintln!("Error: {}", e);
            std::process::exit(1);
        }
    }
}

fn print_help() {
    println!("Sorts CSV data lexicographically.");
}
