pub fn run(args: &[String]) {
    if args.iter().any(|a| a == "--help" || a == "-h") {
        print_help();
        return;
    }

    let delimiter = get_delim(args);
    let has_headers = !get_no_headers(args);
    let input = get_input_file(args);

    let mut condense = None;
    let mut separator = "#".to_string();

    for (i, arg) in args.iter().enumerate() {
        match arg.as_str() {
            "-c" | "--condense" => {
                if i + 1 < args.len() {
                    condense = args[i + 1].parse().ok();
                }
            }
            "-s" | "--separator" => {
                if i + 1 < args.len() {
                    separator = args[i + 1].clone();
                }
            }
            _ => {}
        }
    }

    match CsvReader::new(input, delimiter, has_headers) {
        Ok(mut reader) => {
            let headers = reader.headers().cloned();
            let mut first = true;

            for result in reader.records() {
                if let Ok(record) = result {
                    if !first {
                        println!("{}", separator);
                    }

                    for (i, value) in record.0.iter().enumerate() {
                        let name = if let Some(ref h) = headers {
                            h.0.get(i).map(|s| s.clone()).unwrap_or_else(|| i.to_string())
                        } else {
                            i.to_string()
                        };

                        let display = if let Some(c) = condense {
                            let truncated: String = value.chars().take(c).collect();
                            if value.chars().count() > c {
                                truncated + "..."
                            } else {
                                truncated
                            }
                        } else {
                            value.clone()
                        };

                        println!("{}  {}", name, display);
                    }
                    first = false;
                }
            }
        }
        Err(e) => {
            eprintln!("Error: {}", e);
            std::process::exit(1);
        }
    }
}

fn print_help() {
    println!("Prints flattened records such that fields are labeled separated by a new line.");
}
